#include "ksPanelPercentCalls.h"
#include "ksControllerBoundary.h"
#include <stdexcept>
namespace ks{namespace{PanelPercentPartialTest partialTest=nullptr;using T=PanelPercentTask;using S=T::Stage;struct Point{unsigned location,length;};Point point(S s){switch(s){case S::ReadDivisor:return{0xb2c,2};case S::SetScale:return{0xb2e,4};case S::Multiply:return{0xb32,2};case S::Divide:return{0xb34,2};case S::HoldOutput:return{0xb36,4};case S::SetPrefix:return{0xb3a,2};case S::DispatchPrefix:return{0xb3c,4};case S::AwaitPrefix:case S::DispatchValue:return{0xb40,4};case S::AwaitValue:case S::SetSuffix:return{0xb44,2};case S::DispatchSuffix:return{0xb46,4};case S::AwaitSuffix:case S::RestoreOutput:return{0xb4a,4};case S::Finish:return{0xb4e,2};default:throw std::runtime_error("Invalid panel percent stage");}}}
bool PanelPercentCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0xb2c){if(selected)throw std::runtime_error("Overlapping panel percent");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Panel percent capacity");selected->emplace(h.getSP());++started;}if(!selected||point((**selected).task.stage()).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto&v=h.regs;if(t.child()!=T::Child::None)t.resumeChild();auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(stage).length);auto cost=t.nextClocks();t.advanceBefore(cost,[&](T::Read r){return uint16_t(r==T::Read::Divisor?v[0].e:v[0].r);});switch(stage){case S::ReadDivisor:f.move(v[1].r,int16_t(t.divisor()));break;case S::SetScale:f.move(v[0].e,100);break;case S::Multiply:v[0].er=int32_t(t.product());h.clockI(20);break;case S::Divide:flag(h,8,t.divisor()&0x8000);flag(h,4,!t.divisor());v[0].er=int32_t(t.packedResult());h.clockI(20);break;case S::HoldOutput:f.push(v[6].er);(**selected).depth+=4;break;case S::SetPrefix:f.move(v[6].rl,0xffffff8d);break;case S::DispatchPrefix:case S::DispatchSuffix:f.call(0x976);h.pc=h.makepc(f.next);break;case S::DispatchValue:if(uint8_t(v[0].rl)!=t.value())throw std::runtime_error("Percent value child differs");f.call(0x9dc);h.pc=h.makepc(f.next);break;case S::SetSuffix:f.move(v[6].rl,0x25);break;case S::RestoreOutput:f.pop(v[6].er);(**selected).depth-=4;break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::DispatchPrefix&&stage!=S::DispatchValue&&stage!=S::DispatchSuffix&&stage!=S::Finish)h.pc=h.makepc(point(t.stage()).location);if(h.cycles-before!=cost)throw std::runtime_error("Panel percent clocks differ");return true;}}

